mapper.select:
SELECT SQL_CALC_FOUND_ROWS pr.place_id, pp.name AS placeName, pr.review_id, CASE WHEN pi.pet_type_cd = 'CAT' THEN '고양이' ELSE '강아지' END AS pet_type_nm, fn_codeNm(pi.pet_type_cd, pi.pet_kind_cd, false) AS pet_kind_nm, CONCAT(TIMESTAMPDIFF(MONTH, birth_dt, CURRENT_DATE), '개월') AS birth_dt, CASE WHEN pi.sex = 'FEMALE' THEN '암컷' ELSE '수컷' END AS sex_nm, pr.mb_id, pr.pet_id, pr.point, (SELECT COUNT(*) FROM pet_review_like_mapping WHERE del_fl = 0 AND review_id = pr.review_id) AS like_total_cnt, pr.tag_name, pr.visit_reason, pr.visit_content, IFNULL((SELECT bf_fileurl FROM pet_review_file_mapping prfm INNER JOIN g5_board_file gbf ON gbf.bo_table = 'pet_review' AND prfm.rfm_id = gbf.wr_id WHERE prfm.review_id = pr.review_id ORDER BY prfm.create_ymd LIMIT 1), NULL) AS file_url, (SELECT COUNT(*) FROM pet_review_file_mapping WHERE review_id = pr.review_id AND mb_id = pr.mb_id) AS review_file_count, IFNULL((SELECT CASE WHEN rlm_id > 0 THEN 1 ELSE 0 END FROM pet_review_like_mapping WHERE del_fl = 0 AND review_id = pr.review_id AND mb_id = #{mbId} LIMIT 1), 0) AS like_fl, IFNULL((SELECT rlm_id FROM pet_review_like_mapping WHERE del_fl = 0 AND review_id = pr.review_id AND mb_id = #{mbId} LIMIT 1), 0) AS rlm_id, IFNULL((SELECT CASE WHEN scrap_id > 0 THEN 1 ELSE 0 END FROM pet_review_scrap_mapping WHERE del_fl = 0 AND review_id = pr.review_id AND mb_id = #{mbId} LIMIT 1), 0) AS scrap_fl, IFNULL((SELECT scrap_id FROM pet_review_scrap_mapping WHERE del_fl = 0 AND review_id = pr.review_id AND mb_id = #{mbId} LIMIT 1), 0) AS scrap_id, pr.point, pr.create_ymd FROM pet_review pr INNER JOIN pet_info pi ON pr.mb_id = pi.mb_id AND pr.pet_id = pi.pet_id AND pr.del_fl = pi.del_fl INNER JOIN pet_place pp ON pr.place_id = pp.id AND pr.del_fl = pp.del_fl WHERE pi.del_fl = 0
AND pr.place_id = #{placeId}
ORDER BY pr.create_ymd DESC LIMIT #{pageNo}, #{pageSize};

mapper.insert:
INSERT INTO pet_review_file_mapping (
    review_id,
    mb_id,
    create_id
) VALUES (
    #{reviewId},
    #{mbId},
    #{createId}
);

INSERT INTO pet_review_like_mapping (
    review_id,
    mb_id,
    create_id
) VALUES (
    #{reviewId},
    #{mbId},
    #{createId}
);

INSERT INTO pet_review_scrap_mapping (
    review_id,
    mb_id,
    create_id
) VALUES (
    #{reviewId},
    #{mbId},
    #{createId}
);
